import{f as e,o as t,c as o,a2 as d}from"./chunks/framework.BUDOXiIz.js";const g=JSON.parse('{"title":"Configuración real de Laguna Larga en Procoop","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/12-configuracion-real-laguna-larga.md","filePath":"relevamiento/reglas-negocio/12-configuracion-real-laguna-larga.md","lastUpdated":null}'),r={name:"relevamiento/reglas-negocio/12-configuracion-real-laguna-larga.md"};function i(n,a,s,c,l,p){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="configuracion-real-de-laguna-larga-en-procoop" tabindex="-1">Configuración real de Laguna Larga en Procoop <a class="header-anchor" href="#configuracion-real-de-laguna-larga-en-procoop" aria-label="Permalink to &quot;Configuración real de Laguna Larga en Procoop&quot;">​</a></h1><p>Lectura de solo consulta (<code>SELECT</code>) de la base <code>PR_LAG_DEMO</code> en la PC demo, hecha el 3/11/2026. Confirma qué ramas del código de Procoop aplican a la Cooperativa Eléctrica Laguna Larga. Complementa a <a href="./05-cobranzas-cajas-y-entes-recaudadores">05 - Cobranzas y entes recaudadores</a> (sección 9) y a <a href="./09-parametros-y-configuracion">09 - Parámetros</a>.</p><p><strong>Advertencia:</strong> <code>PR_LAG_DEMO</code> es la base de demostración. Por sus datos (pagos hasta agosto de 2026) parece una copia de producción, pero la configuración actual puede diferir y hay que validarla con la cooperativa antes de migrar. Contiene datos personales reales.</p><h2 id="_1-sigla-de-la-cooperativa" tabindex="-1">1. Sigla de la cooperativa <a class="header-anchor" href="#_1-sigla-de-la-cooperativa" aria-label="Permalink to &quot;1. Sigla de la cooperativa&quot;">​</a></h2><p>El parámetro <strong>2264 vale <code>LAG</code></strong>. Consecuencias en el código:</p><ul><li>Aplica la rama exclusiva de Laguna Larga del exportador SIRO, que antepone un &quot;0&quot; al convenio en el código de barras (<code>PR/E_SIRO.cs:134</code>).</li><li>Aplica la marca <code>esLAG</code> de los informes ENARGAS (<code>clsEnargas2.cs:1402</code>): la cooperativa factura gas.</li><li><strong>No</strong> aplican las ramas <code>&quot;LAGU&quot;</code> (<code>PR/RedLink_1.cs:38-97</code>) ni <code>&quot;FAL&quot;</code>. Esto cierra la duda abierta del documento 05: el prefijo <code>FAL_</code> del enum del importador es solo un nombre heredado.</li></ul><h2 id="_2-entes-recaudadores-tabla-bancos" tabindex="-1">2. Entes recaudadores (tabla <code>BANCOS</code>) <a class="header-anchor" href="#_2-entes-recaudadores-tabla-bancos" aria-label="Permalink to &quot;2. Entes recaudadores (tabla `BANCOS`)&quot;">​</a></h2><p>La base tiene 3 entes:</p><table tabindex="0"><thead><tr><th>Campo</th><th>RED LINK</th><th>SIRO</th><th>DOCUMENTOS A COBRAR</th></tr></thead><tbody><tr><td><code>COD_BAN</code></td><td>1</td><td>2</td><td>3</td></tr><tr><td><code>CONVENIO</code></td><td>D67</td><td>5150071619</td><td>(vacío)</td></tr><tr><td><code>COD_ARC</code>: importador de la rendición</td><td><strong>264</strong> <code>FAL_RedLink</code>, el propio de LAG (<code>Entidades.LAG/Red_Link.cs</code>)</td><td><strong>271</strong> <code>PR_SIRO_Int</code>, &quot;Banco Roela (SIRO) - Integrado&quot; (clase <code>Siro_Integrado</code>, por API)</td><td>0 (ninguno)</td></tr><tr><td><code>COD_ARC2</code>: exportador de la deuda</td><td><strong>159</strong> <code>PR_LINK_08</code> (clase <code>E_RedLink_19_10</code>, &quot;Identificador 10 de 19 dígitos&quot;)</td><td><strong>140</strong> <code>PR_SIRO</code> (clase <code>E_SIRO</code>)</td><td>0 (ninguno)</td></tr><tr><td><code>ARC_CONFIG</code>: forma de identificar el comprobante</td><td>0 (por defecto)</td><td>0 (por defecto)</td><td>0</td></tr><tr><td><code>CAJA</code>: caja virtual</td><td>101</td><td>102</td><td>300</td></tr><tr><td><code>COD_BANT</code>: cuenta bancaria de acreditación</td><td>2</td><td>5</td><td>13</td></tr><tr><td><code>DIFERIR</code></td><td>1: difiere solo la mora y cobra el recargo entre vencimientos</td><td>1</td><td>0</td></tr><tr><td><code>PERFUETER</code> + <code>FUETERBAN</code></td><td>True + 5: <strong>acepta pagos sin límite de vencimiento</strong></td><td>True + 5</td><td>True + 5</td></tr><tr><td><code>PERMITE_ENTREGA</code>: pagos parciales</td><td>No</td><td>No</td><td>No</td></tr><tr><td><code>COBVTO1</code></td><td>No</td><td>No</td><td>No</td></tr><tr><td><code>RECARGO3VTO</code>: cobra mora pasado el último vencimiento</td><td>Sí</td><td>Sí</td><td>No</td></tr><tr><td><code>CONCILIACION_AUTO</code></td><td>No</td><td>No</td><td>No</td></tr><tr><td>Comisión (<code>TRASLADAR</code>, <code>FORMA_CAL</code>, <code>IMPO_*</code>)</td><td>Sin comisión</td><td>Sin comisión</td><td>Sin comisión</td></tr></tbody></table><p>Sobre <code>FUETERBAN = 5</code>: en <code>Importador_Base.cs:1823</code> y <code>:1959</code>, con <code>PERFUETER</code> activo, los valores 0 a 4 eligen el vencimiento máximo aceptado. Cualquier otro valor toma <code>DateTime.MaxValue</code>, es decir que no hay tope.</p><p><strong>Lectura:</strong></p><ul><li><strong>Red Link</strong>: <ul><li>La rendición se identifica por cuenta, servicio e importe; es el importador propio documentado en el doc 05, sección 9.2.</li><li>El envío de deuda usa el formato genérico de 19 dígitos con identificador de 10.</li><li>El convenio (código de ente) es <code>D67</code>.</li></ul></li><li><strong>SIRO</strong>: <ul><li>El envío se hace por archivo (<code>E_SIRO</code>, con la rama LAG del &quot;0&quot;).</li><li>La rendición está configurada con el importador <strong>integrado por API</strong>. Sin embargo, el parámetro 2807 (&quot;Utiliza el servicio de SIRO - API Gestión&quot;) vale 0, así que hay que confirmar si la API está realmente operativa o si se rinde por archivo.</li></ul></li><li><strong>DOCUMENTOS A COBRAR</strong> no tiene importador ni exportador. Es un &quot;ente&quot; usado como caja o cartera (caja 300) para documentos o cheques, sin interfaz de archivos, como se suponía.</li><li>Ningún ente admite pagos parciales. Todos aceptan pagos fuera de término sin límite y aplican el recargo que corresponda.</li></ul><h2 id="_3-pasarelas-de-pago-online" tabindex="-1">3. Pasarelas de pago online <a class="header-anchor" href="#_3-pasarelas-de-pago-online" aria-label="Permalink to &quot;3. Pasarelas de pago online&quot;">​</a></h2><p>Esta sección cruza el <a href="./13-pasarelas-de-pago-e-interbanking">documento 13</a> con la base. Los valores de las credenciales no se leyeron; solo se verificó si cada parámetro tiene contenido, por el largo del texto.</p><p><strong>Credenciales cargadas.</strong> Solo SIRO tiene datos:</p><ul><li>Usuario y clave del botón de pago: parámetros 2492 y 2493.</li><li>CUIT y clave de la API de gestión: parámetros 2804 y 2805.</li></ul><p>Están <strong>vacías</strong> las de Pagos360 (901, 2922), MercadoPago (2553), NaranjaX (2756), Macro (2765), PayFun (2793), Pagos TIC (2877), SiPago (2956), ProntoPago (2969), ProvinciaNet (3046) y Helipagos (3077). La tabla <code>INTERBANKING</code> está vacía, así que <strong>Interbanking no se usa</strong>.</p><p><strong>Solicitudes de pago (tabla <code>PAGOS360</code>).</strong> Hay 128.776 solicitudes, todas con API 1 (SIRO). Van desde el 18/07/2023 hasta el 06/08/2026, lo que indica que la base demo es una copia de producción de agosto de 2026 y que <strong>sus datos son reales</strong>.</p><p>Por tipo de solicitud (enum <code>EntidadDigital.Tipo</code>):</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Solicitudes</th><th>Imputadas</th><th>Registradas sin pago</th><th>Pendientes</th><th>Rechazadas</th></tr></thead><tbody><tr><td>7 – Prepaga CoopOnline (energía prepaga desde el portal o la app)</td><td>89.842</td><td>52.899</td><td>35.400</td><td>1.236</td><td>306</td></tr><tr><td>9 – Cobranza CoopOnline (facturas pagadas desde el portal o la app)</td><td>38.322</td><td>23.776</td><td>13.942</td><td>479</td><td>124</td></tr><tr><td>6 – Web</td><td>612</td><td>612</td><td>0</td><td>0</td><td>0</td></tr></tbody></table><p>Además, hay una solicitud en estado &quot;Pagado&quot; sin imputar en cada uno de los tipos 7 y 9. Ninguna solicitud tiene QR.</p><p><strong>Lectura:</strong></p><ul><li>La única pasarela online de Laguna Larga es el <strong>botón de pago SIRO</strong>, usado desde CoopOnline.</li><li>Casi 7 de cada 10 solicitudes son de <strong>energía prepaga</strong>, así que la cooperativa tiene medidores prepagos en uso. Esto hay que tenerlo en cuenta en el alcance del piloto.</li><li>Cerca del 38 % de las solicitudes queda &quot;Registrada&quot; sin pago: son links generados que el usuario no pagó. GoodApps debería vencerlas o limpiarlas.</li><li>Están cargadas las credenciales de la API de gestión de SIRO, pero el parámetro 2807 que la activa vale 0. Probablemente se configuró y nunca se activó, o se desactivó.</li></ul><h2 id="_4-parametros-relevantes" tabindex="-1">4. Parámetros relevantes <a class="header-anchor" href="#_4-parametros-relevantes" aria-label="Permalink to &quot;4. Parámetros relevantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parámetro</th><th>Valor</th><th>Significado (catálogo del doc 09)</th></tr></thead><tbody><tr><td>2264</td><td><code>LAG</code></td><td>Sigla de la cooperativa</td></tr><tr><td>2085</td><td>10.4.6.722</td><td>Versión de la capa de datos</td></tr><tr><td>518</td><td>COOPERATIVA ELECTRICA LAGUNA L…</td><td>Razón social</td></tr><tr><td>74</td><td>1 (&quot;Variable Porcentaje&quot;)</td><td>Tipo de recargo por pago fuera de término en la factura</td></tr><tr><td>1011</td><td>3</td><td>Diferir <strong>todos</strong> los intereses a la próxima factura</td></tr><tr><td>273</td><td>No</td><td>Los intereses se emiten como nota de débito, no como factura</td></tr><tr><td>600</td><td>0,1</td><td>Recargo diario en caja (tasa diaria fija)</td></tr><tr><td>609</td><td>0</td><td>Sin interés mínimo en caja</td></tr><tr><td>606 / 307</td><td>1</td><td>Concepto de &quot;INTERES POR MORA&quot; (código de producto 1)</td></tr><tr><td>719</td><td>9</td><td>Concepto de &quot;COBRANZA REMOTA&quot;</td></tr><tr><td>2292</td><td>1 (Estándar)</td><td>Variante estándar del cálculo de intereses de facturas impagas</td></tr><tr><td>2202</td><td>1 (CANDIDATOS)</td><td>Instancia inicial de la gestión de mora</td></tr><tr><td>321, 324, 375, 462</td><td>No</td><td>No exige cobrar primero las facturas más antiguas ni la deuda notificada completa</td></tr><tr><td>2263</td><td>Sí</td><td>Permite facturas en cuotas</td></tr><tr><td>727</td><td>Sí</td><td>La venta y la cobranza esperan la autorización de ARCA</td></tr><tr><td>2712</td><td>5000</td><td>Máximo de comprobantes por lote de facturación electrónica</td></tr><tr><td>2515</td><td>3.958.316</td><td>Importe desde el cual se emite Factura de Crédito MiPyME</td></tr><tr><td>2315</td><td>50</td><td>Cuentas por grupo en la facturación masiva</td></tr><tr><td>2807</td><td>No</td><td>No usa la API de gestión de SIRO</td></tr><tr><td>3094</td><td>0</td><td>Sin concepto de anticipo por energía inyectada: <strong>no hay prosumidores configurados</strong></td></tr></tbody></table><h2 id="_5-implicancias-para-goodapps" tabindex="-1">5. Implicancias para GoodApps <a class="header-anchor" href="#_5-implicancias-para-goodapps" aria-label="Permalink to &quot;5. Implicancias para GoodApps&quot;">​</a></h2><ul><li>La migración de la cobranza de Laguna Larga necesita, como mínimo: <ul><li>el formato Red Link de envío (19/10);</li><li>el importador Red Link propio, con identificación por cuenta, servicio e importe;</li><li>el exportador SIRO con el &quot;0&quot; antepuesto al convenio;</li><li>la rendición SIRO, por API o por archivo según se confirme.</li></ul></li><li>Hay que soportar pagos fuera de término sin tope, recargo por mora pasado el último vencimiento y diferimiento de todos los intereses a la próxima factura (parámetro 1011 = 3).</li><li>No hacen falta pagos parciales en entes ni comisiones trasladadas al usuario.</li><li>Las cuotas (2263) y la espera de CAE en caja (727) sí están activas.</li><li><strong>Pasarelas:</strong> para el piloto alcanza con el botón de pago SIRO, que cubre la cobranza de facturas y la recarga de energía prepaga desde el portal y la app. Pagos360, MercadoPago, las demás pasarelas e Interbanking no son necesarios para LAG.</li><li><strong>Energía prepaga:</strong> es el uso principal del pago online, así que el portal y la app de GoodApps deben soportarla desde el inicio.</li></ul><h2 id="_6-dudas-abiertas" tabindex="-1">6. Dudas abiertas <a class="header-anchor" href="#_6-dudas-abiertas" aria-label="Permalink to &quot;6. Dudas abiertas&quot;">​</a></h2><ul><li>Confirmar si la configuración de producción coincide con esta base demo.</li><li>SIRO: importador 271 por API con el parámetro 2807 en 0. ¿Cómo rinde hoy realmente la cooperativa?</li><li>Tasa diaria de 0,1 % (parámetro 600): confirmar si es la tasa vigente o un valor de prueba.</li><li>Energía prepaga: ¿qué sistema de medidores prepagos usa Laguna Larga y cómo se integra con Procoop al acreditar una recarga?</li><li>Hay 2 solicitudes &quot;Pagado&quot; sin imputar: ¿es un caso normal o quedaron colgadas?</li><li>Sin prosumidores configurados (3094 = 0): confirmar si Laguna Larga tiene usuarios con generación distribuida.</li></ul>',29)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
